// Function to find the nth number in the sequence
int findNthNumber(int n) {
    // Base cases
    if (n == 0) return 0;
    if (n == 1) return -1;
    if (n == 2) return -1;

    // Initialize the first three numbers
    int a = 0, b = -1, c = -1, d;

    // Calculate the nth number iteratively
    for (int i = 3; i <= n; i++) {
        d = a + b + c;
        a = b;
        b = c;
        c = d;
    }

    return d;
}

int main() {
    int n;
    cout << "Enter the value of n to find the nth number in the sequence: ";
    cin >> n;

    // Check if the input is valid
    if (n < 0) {
